    # 2) If there is an adjacent enemy and no ally to help, stay or move away.
    # 3) Else if goal is provided, bias toward it.
    # 4) Otherwise wander slightly to spread.

    # Helper to check adjacent cells for a value in a 2D grid-like observation
    def adjacent_contains(delta_x, delta_y, target_types):
        nx, ny = x + delta_x, y + delta_y
        # Safely access grid if provided as dict or list of lists
        if isinstance(grid, dict):
            cell = grid.get((nx, ny))
        elif isinstance(grid, list):
            if 0 <= ny < len(grid) and 0 <= nx < len(grid[ny]):
