    if goal is not None:
        gx = goal.get("x", x)
        gy = goal.get("y", y)
        dx = 0 if gx == x else (1 if gx > x else -1)
        dy = 0 if gy == y else (1 if gy > y else -1)
        return [dx, dy]

    # Otherwise, basic wandering: prefer moving to a new cell not equal to current
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            if dx == 0 and dy == 0:
                continue
            return [dx, dy]

    # Fallback (shouldn't reach here)
    return [0, 0]

